        && same_bytes(&a.api_version, &b.api_version)
        && same_bytes(&a.driver_version, &b.driver_version)
        && same_bytes(&a.vendor_id, &b.vendor_id)
        && same_bytes(&a.device_id, &b.device_id)
        && same_bytes(&a.device_type, &b.device_type)
        && same_bytes(&a.pipeline_cache_uuid, &b.pipeline_cache_uuid)
        && same_bytes(&a.limits.max_image_dimension_1d, &b.limits.max_image_dimension_1d)
        && same_bytes(&a.limits.max_image_dimension_2d, &b.limits.max_image_dimension_2d)
        && same_bytes(&a.limits.max_image_dimension_3d, &b.limits.max_image_dimension_3d)
        && same_bytes(&a.limits.max_image_dimension_cube, &b.limits.max_image_dimension_cube)
        && same_bytes(&a.limits.max_image_array_layers, &b.limits.max_image_array_layers)
        && same_bytes(&a.limits.max_texel_buffer_elements, &b.limits.max_texel_buffer_elements)
        && same_bytes(&a.limits.max_uniform_buffer_range, &b.limits.max_uniform_buffer_range)
        && same_bytes(&a.limits.max_storage_buffer_range, &b.limits.max_storage_buffer_range)
        && same_bytes(&a.limits.max_push_constants_size, &b.limits.max_push_constants_size)
        && same_bytes(&a.limits.max_memory_allocation_count, &b.limits.max_memory_allocation_count)
        && same_bytes(&a.limits.max_sampler_allocation_count, &b.limits.max_sampler_allocation_count)
        && same_bytes(&a.limits.buffer_image_granularity, &b.limits.buffer_image_granularity)
        && same_bytes(&a.limits.sparse_address_space_size, &b.limits.sparse_address_space_size)
        && same_bytes(&a.limits.max_bound_descriptor_sets, &b.limits.max_bound_descriptor_sets)
        && same_bytes(&a.limits.max_per_stage_descriptor_samplers, &b.limits.max_per_stage_descriptor_samplers)
        && same_bytes(&a.limits.max_per_stage_descriptor_uniform_buffers, &b.limits.max_per_stage_descriptor_uniform_buffers)
        && same_bytes(&a.limits.max_per_stage_descriptor_storage_buffers, &b.limits.max_per_stage_descriptor_storage_buffers)
